// ── set these two, then run List once → paste the nonce Read the claim returned here → enable Verify listing ──
const TAIFOON_LISTING = ''; // the nonce Read the claim returned (empty until you claim)
const ADDRESS = '0xYOUR_PAYOUT_ADDRESS'; // your payout address (a label for the seller of record; nothing is signed with it)
// The seller's card (GET), ERC-8004 registration-v1 shaped, kind n8n: the Hire webhook is the endpoint,
// on the host this card was read on (behind a proxy: its forwarded host and scheme), so there is no URL to edit.
const h = $('Card').first().json.headers || {};
const endpoint = `${h['x-forwarded-proto'] || 'https'}://${h['x-forwarded-host'] || h.host}/webhook/tfn-mcp-word-count`;
return [{ json: { card: {
  type: 'https://eips.ethereum.org/EIPS/eip-8004#registration-v1',
  name: "n8n word counter",
  description: "An n8n workflow that counts the words of a text. Hire it with a task of class chat.word_count: Count the words in: \"…\" (reply with the number of words). It answers { words } and echoes the offer nonce.",
  kind: 'n8n', address: ADDRESS, endpoint,
  services: [{ name: 'webhook', endpoint, version: 'taifoon-offer-v1' }],
  skills: ['word-count', 'text', 'count', 'n8n'],
  classes: ['chat.word_count'],
  price_usdc: 0.05,
  verify: ['self'],
  taifoon_listing: TAIFOON_LISTING,
  supportedTrust: ['reputation'],
} } }];

// ADDRESS must equal the card's address: the payout address you listed with (replace the placeholder in BOTH Code nodes).
const ADDRESS = '0xYOUR_PAYOUT_ADDRESS';
// The §2 offer as the Hire webhook received it: { jobId, chain, client, provider, evaluator, verify, phase, state, budget_usdc,
// task, required_skills, reply_to, nonce } (a class probe also carries class_probe: true).
const body = ($('Hire').first().json || {}).body || {};
const base = { nonce: body.nonce ?? null, provider: ADDRESS.toLowerCase() };
// The reply is ALWAYS { nonce, provider, status: delivered | refused, result }, answered 200.
const reply = (status, result) => [{ json: { ...base, reply: { ...base, status, result } } }];
const refuse = (error) => reply('refused', { error });
// The harvester's liveness probe ({ kind: "taifoon.probe.v1", probe: true, … }) does no work: READY. A class probe does the work.
if (body.class_probe !== true && (body.probe === true || body.kind === 'taifoon.probe.v1')) return reply('delivered', 'READY');
const task = typeof body.task === 'string' ? body.task : '';
// Task: chat.word_count: Count the words in: "<text>" (reply with the number of words)
const START = 'Count the words in: "', END = '" (reply';
const i = task.indexOf(START), k = task.lastIndexOf(END);
if (i < 0 || k < i + START.length) return refuse('the task carries no text; expected: Count the words in: "<text>" (reply with the number of words)');
const text = task.slice(i + START.length, k);
// Words are runs of non-whitespace; an empty or blank text has 0. The result carries this one number and nothing else.
const words = text.trim().split(/\s+/).filter(Boolean).length;
return reply('delivered', { words });

// The MCP Client answers the tool's result; taifoon_op returns the /v1 answer as JSON text (content[0].text) or as an object.
const r = $json || {};
// Claim listing (MCP) ships disabled: its input (the Seller fields) passes through until you set CARD_URL and enable it
if ('CARD_URL' in r) return [{ json: { listing_id: null, next: /YOUR-N8N-HOST/.test(r.CARD_URL) ? 'set CARD_URL and PAYOUT_ADDRESS in Seller (and ADDRESS in both Code nodes), enable Claim listing (MCP), run List once' : 'enable Claim listing (MCP), run List once' } }];
if (r.error) return [{ json: { listing_id: null, refused: String(r.error.message || r.error).replace(/\s+/g, ' ').slice(0, 300), next: 'fix what the refusal names in Seller, run List once again' } }];
const t = (r.content && r.content[0] && r.content[0].text) || r.result || r;
// a refusal comes as '<status>: <json>' (taifoon_op), an answer as the JSON text itself
let j = t; if (typeof t === 'string') { const m = t.match(/^(\d{3}): ([\s\S]*)$/); try { j = JSON.parse(m ? m[2] : t); if (m) j.http_status = Number(m[1]); } catch { j = { raw: t }; } }
const listing = j.listing || {};
const nonce = (j.challenge && j.challenge.nonce) || null;
return [{ json: { listing_id: listing.id || null, state: listing.state || null, nonce, problems: j.problems || null,
  next: nonce ? 'paste the nonce into Card JSON TAIFOON_LISTING, set LISTING_ID in Seller, enable Verify listing and Register for dispatch, run List once again' : 'the claim did not answer a nonce: read problems' } }];

// One line per offer: when, what came back. Settled → legs written → accrued → split happen in the layer on an outside buyer's paid hire;
// PAID is the seller's share in Base USDC to the card's payout address, sent by Taifoon's vault signer (held until the owner turns keyed payouts on).
const r = $json || {};
if (r.error) return [{ json: { ok: false, refused: String(r.error.message || r.error).replace(/\s+/g, ' ').slice(0, 300), next: 'set provider in Offers (MCP) to the payout address you listed with, then run again' } }];
const t = (r.content && r.content[0] && r.content[0].text) || r.result || r;
// a refusal comes as '<status>: <json>' (taifoon_op), an answer as the JSON text itself
let j = t; if (typeof t === 'string') { const m = t.match(/^(\d{3}): ([\s\S]*)$/); try { j = JSON.parse(m ? m[2] : t); if (m) j.http_status = Number(m[1]); } catch { j = { raw: t }; } }
const rows = j.handshakes || j.offers || j.rows || [];
return [{ json: { offers: rows.length, delivered: rows.filter((h) => (h.delivery && h.delivery.status) === 'delivered' || h.status === 'delivered').length,
  rows: rows.slice(0, 20).map((h) => ({ id: h.handshake_id || h.id || null, at: h.created_at || h.at || null, task: h.task || null, delivery: (h.delivery && h.delivery.status) || h.status || null })),
  paid: 'HELD: the seller\'s share is paid by Taifoon\'s vault signer on its own venue (Base USDC); nothing here moves money' } }];
